type ChatHTTPService interface {
	GetBootstrap(ctx context.Context, req *GetBootstrapReq) (r *BootstrapResp, err error)

	CreateWorkspace(ctx context.Context, req *CreateWorkspaceReq) (r *CreateWorkspaceResp, err error)

	ListWorkspaceMembers(ctx context.Context, req *ListWorkspaceMembersReq) (r *ListWorkspaceMembersResp, err error)

	CreateWorkspaceInvite(ctx context.Context, req *CreateWorkspaceInviteReq) (r *CreateWorkspaceInviteResp, err error)

	GetInvite(ctx context.Context, req *GetInviteReq) (r *GetInviteResp, err error)

	AcceptInvite(ctx context.Context, req *AcceptInviteReq) (r *AcceptInviteResp, err error)

	RemoveWorkspaceMember(ctx context.Context, req *RemoveWorkspaceMemberReq) (r *EmptyResp, err error)

	ListConversations(ctx context.Context, req *ListConversationsReq) (r *ListConversationsResp, err error)

	CreateConversation(ctx context.Context, req *CreateConversationReq) (r *ConversationResp, err error)

	AddConversationMember(ctx context.Context, req *AddConversationMemberReq) (r *ConversationResp, err error)

	RemoveConversationMember(ctx context.Context, req *RemoveConversationMemberReq) (r *ConversationResp, err error)

	ListMessages(ctx context.Context, req *ListMessagesReq) (r *ListMessagesResp, err error)

	GetMessage(ctx context.Context, req *GetMessageReq) (r *MessageResp, err error)

	SendMessage(ctx context.Context, req *SendMessageReq) (r *MessageResp, err error)

	EditMessage(ctx context.Context, req *EditMessageReq) (r *MessageResp, err error)

	RetractMessage(ctx context.Context, req *RetractMessageReq) (r *MessageResp, err error)

	PutReaction(ctx context.Context, req *PutReactionReq) (r *ReactionsResp, err error)

	DeleteReaction(ctx context.Context, req *DeleteReactionReq) (r *ReactionsResp, err error)

	MarkRead(ctx context.Context, req *MarkReadReq) (r *MarkReadResp, err error)

	GetReadReceipts(ctx context.Context, req *GetReadReceiptsReq) (r *ReadReceiptsResp, err error)

	SetNotificationLevel(ctx context.Context, req *SetNotificationLevelReq) (r *NotificationLevelResp, err error)

	SearchWorkspaceMessages(ctx context.Context, req *SearchWorkspaceMessagesReq) (r *WorkspaceSearchPageResp, err error)

	GetAttention(ctx context.Context, req *GetAttentionReq) (r *AttentionPageResp, err error)

	Sync(ctx context.Context, req *SyncReq) (r *SyncResp, err error)

	UploadAttachment(ctx context.Context, req *UploadAttachmentReq) (r *AttachmentResp, err error)

	GetAttachmentUpload(ctx context.Context, req *GetAttachmentUploadReq) (r *AttachmentResp, err error)

	DeletePendingAttachment(ctx context.Context, req *DeletePendingAttachmentReq) (r *EmptyResp, err error)

	DownloadAttachment(ctx context.Context, req *DownloadAttachmentReq) (r *DownloadAttachmentResp, err error)
}
